<?php
require_once __DIR__ . '/../config/conexion.php';require_once __DIR__ . '/../config/seguridad.php';exigir_rol('Admin');
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
$id=trim($_POST['id_usuario_donante']??'');$nombre=trim($_POST['nombre_donante']??'');$correo=trim($_POST['correo_donante']??'');$clave=$_POST['contrasena_donante']??'';$fecha=$_POST['fecha_registro_donante']??'';
if($id===''||$nombre===''||!filter_var($correo,FILTER_VALIDATE_EMAIL)||$clave===''||$fecha===''){$error='Completa todos los campos y verifica que el correo sea válido.';}
else{$conexion=conectar();$sql="INSERT INTO Donante (id_usuario_donante,nombre_donante,correo_donante,contraseña_donante,fecha_registro_donante) VALUES (?,?,?,?,?)";$stmt=mysqli_prepare($conexion,$sql);
if($stmt){mysqli_stmt_bind_param($stmt,'sssss',$id,$nombre,$correo,$clave,$fecha);if(mysqli_stmt_execute($stmt)){mysqli_stmt_close($stmt);mysqli_close($conexion);header('Location: registro_exitoso.php?tipo=donante');exit();}$error=mysqli_errno($conexion)===1062?'Ya existe un usuario con ese identificador.':'No fue posible guardar el donante. Revisa los datos.';error_log(mysqli_error($conexion));mysqli_stmt_close($stmt);}else{$error='No fue posible preparar el registro.';error_log(mysqli_error($conexion));}mysqli_close($conexion);}
}
?>
